scanf("%d",&a[i][j]);
}
for(i=0;i<5;i++)
{
for(j=0;j<5;j++)
b[i][j]=a[j][i];} //转置
FILE *fp;
if((fp=fopen("matrix.txt","w"))==NULL)
{
printf("error\n");exit(0);
}
for(i=0;i<5;i++)
{
j=0;
fprintf(fp,"%d,%d,%d,%d,%d",b[i][j],b[i][j+1],b[i][j+2],b[i][j+3],b[i][j+4]);
}
